public void testLoanProductConfiguration() {
    final String proposedAmount = "5000";
    JsonObject loanProductConfigurationAsTrue = new JsonObject();
    loanProductConfigurationAsTrue = this.createLoanProductConfigurationDetail(loanProductConfigurationAsTrue, true);
    JsonObject loanProductConfigurationAsFalse = new JsonObject();
    loanProductConfigurationAsFalse = this.createLoanProductConfigurationDetail(loanProductConfigurationAsFalse, false);
    final Integer clientID = ClientHelper.createClient(this.requestSpec, this.responseSpec, "01 January 2012");
    Integer loanProductID = this.loanTransactionHelper.getLoanProductId(new LoanProductTestBuilder().withAmortizationTypeAsEqualInstallments().withRepaymentTypeAsMonth().withRepaymentAfterEvery("1").withRepaymentStrategy(LoanProductTestBuilder.DEFAULT_STRATEGY).withInterestTypeAsDecliningBalance().withInterestCalculationPeriodTypeAsDays().withInArrearsTolerance("10").withMoratorium("2", "3").withLoanProductConfiguration(loanProductConfigurationAsTrue).build(null));
    System.out.println("-----------------------LOAN PRODUCT CREATED WITH ATTRIBUTE CONFIGURATION AS TRUE--------------------------" + loanProductID);
    Integer loanID = applyForLoanApplicationWithProductConfigurationAsTrue(clientID, loanProductID, proposedAmount);
    System.out.println("------------------------LOAN CREATED WITH ID------------------------------" + loanID);
    loanProductID = this.loanTransactionHelper.getLoanProductId(new LoanProductTestBuilder().withAmortizationTypeAsEqualInstallments().withRepaymentTypeAsMonth().withRepaymentAfterEvery("1").withRepaymentStrategy(LoanProductTestBuilder.DEFAULT_STRATEGY).withInterestTypeAsDecliningBalance().withInterestCalculationPeriodTypeAsDays().withInArrearsTolerance("10").withMoratorium("2", "3").withLoanProductConfiguration(loanProductConfigurationAsFalse).build(null));
