     * USD--success scenario
     */
    final Integer clientChargeId = ClientHelper.addChargesForClient(this.requestSpec, this.responseSpec, clientId, ClientHelper.getSpecifiedDueDateChargesClientAsJSON(chargeId.toString(), "29 October 2011"));
    Assert.assertNotNull(clientChargeId);
    final String clientChargePaidTransactionId = ClientHelper.payChargesForClients(this.requestSpec, this.responseSpec, clientId, clientChargeId, ClientHelper.getPayChargeJSON("25 AUGUST 2015", "10"));
    Assert.assertNotNull(clientChargePaidTransactionId);
    isValidOutstandingAmount(ClientHelper.getClientCharge(requestSpec, responseSpec, clientId.toString(), clientChargeId.toString()), (float) 190.0);
    /**
     * Revert the paid client charge transaction by passing the
     * clientChargePaidTransactionId and ensure the same is reverted.
     */
    final Integer undoTrxnId = ClientHelper.revertClientChargeTransaction(this.requestSpec, this.responseSpec, clientId.toString(), clientChargePaidTransactionId);
    Assert.assertNotNull(undoTrxnId);
    isReversedTransaction(clientId.toString(), undoTrxnId.toString());
    /**
     * Now pay client charge for 20 USD and ensure the outstanding amount is
     * updated properly
     */
    ResponseSpecification responseSpecFailure = new ResponseSpecBuilder().expectStatusCode(400).build();
    final String responseId_futureDate_failure = ClientHelper.payChargesForClients(this.requestSpec, responseSpecFailure, clientId, clientChargeId, ClientHelper.getPayChargeJSON("28 AUGUST 2016", "20"));
    Assert.assertNull(responseId_futureDate_failure);
