    final String waiveOffClientChargeTransactionId = ClientHelper.waiveChargesForClients(this.requestSpec, this.responseSpec, clientId, clientChargeId, ClientHelper.getWaiveChargeJSON("100", clientChargeId.toString()));
    Assert.assertNotNull(waiveOffClientChargeTransactionId);
    /**
     * Revert the waived off client charge transaction by passing the
     * waiveOffClientChargeTransactionId and ensured the transaction is
     * reversed.
     */
    final Integer undoWaiveTrxnId = ClientHelper.revertClientChargeTransaction(this.requestSpec, this.responseSpec, clientId.toString(), waiveOffClientChargeTransactionId);
    Assert.assertNotNull(undoWaiveTrxnId);
    isReversedTransaction(clientId.toString(), undoWaiveTrxnId.toString());
    /**
     * pay client charge before client activation date and ensured its a
     * failure test case
     */
    final String responseId_activationDate_failure = ClientHelper.payChargesForClients(this.requestSpec, responseSpecFailure, clientId, clientChargeId, ClientHelper.getPayChargeJSON("30 October 2011", "20"));
    Assert.assertNull(responseId_activationDate_failure);
    /**
     * pay client charge more than outstanding amount amount and ensured its
     * a failure test case
     */
    final String responseId_moreAmount_failure = ClientHelper.payChargesForClients(this.requestSpec, responseSpecFailure, clientId, clientChargeId, ClientHelper.getPayChargeJSON("25 AUGUST 2015", "300"));
