@Test
public void testFinancialActivityAccounts() {
    /**
     * Create a Liability and an Asset Transfer Account *
     */
    Account liabilityTransferAccount = accountHelper.createLiabilityAccount();
    Account assetTransferAccount = accountHelper.createAssetAccount();
    Assert.assertNotNull(assetTransferAccount);
    Assert.assertNotNull(liabilityTransferAccount);
    /**
     * Create A Financial Activity to Account Mapping *
     */
    Integer financialActivityAccountId = (Integer) financialActivityAccountHelper.createFinancialActivityAccount(liabilityTransferFinancialActivityId, liabilityTransferAccount.getAccountID(), responseSpec, CommonConstants.RESPONSE_RESOURCE_ID);
    Assert.assertNotNull(financialActivityAccountId);
    /**
     * Fetch Created Financial Activity to Account Mapping and validate
     * created values
     */
    assertFinancialActivityAccountCreation(financialActivityAccountId, liabilityTransferFinancialActivityId, liabilityTransferAccount);
    /**
     * Update Existing Financial Activity to Account Mapping and assert
     * changes
     */
    Account newLiabilityTransferAccount = accountHelper.createLiabilityAccount();
    Assert.assertNotNull(newLiabilityTransferAccount);
    HashMap changes = (HashMap) financialActivityAccountHelper.updateFinancialActivityAccount(financialActivityAccountId, liabilityTransferFinancialActivityId, newLiabilityTransferAccount.getAccountID(), responseSpec, CommonConstants.RESPONSE_CHANGES);
    Assert.assertEquals(newLiabilityTransferAccount.getAccountID(), changes.get("glAccountId"));
    /**
     * Validate update works correctly *
     */
    assertFinancialActivityAccountCreation(financialActivityAccountId, liabilityTransferFinancialActivityId, newLiabilityTransferAccount);
    /**
     * Update with Invalid Financial Activity should fail *
     */
    List<HashMap> invalidFinancialActivityUpdateError = (List<HashMap>) financialActivityAccountHelper.updateFinancialActivityAccount(financialActivityAccountId, 232, newLiabilityTransferAccount.getAccountID(), responseSpecForValidationError, CommonConstants.RESPONSE_ERROR);
    assertEquals("validation.msg.financialactivityaccount.financialActivityId.is.not.one.of.expected.enumerations", invalidFinancialActivityUpdateError.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    /**
     * Creating Duplicate Financial Activity should fail *
     */
    List<HashMap> duplicateFinancialActivityAccountError = (List<HashMap>) financialActivityAccountHelper.createFinancialActivityAccount(liabilityTransferFinancialActivityId, liabilityTransferAccount.getAccountID(), responseSpecForDomainRuleViolation, CommonConstants.RESPONSE_ERROR);
    assertEquals(DuplicateFinancialActivityAccountFoundException.getErrorcode(), duplicateFinancialActivityAccountError.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    /**
     * Associating incorrect GL account types with a financial activity
     * should fail
     */
    List<HashMap> invalidFinancialActivityAccountError = (List<HashMap>) financialActivityAccountHelper.updateFinancialActivityAccount(financialActivityAccountId, assetTransferFinancialActivityId, newLiabilityTransferAccount.getAccountID(), responseSpecForDomainRuleViolation, CommonConstants.RESPONSE_ERROR);
    assertEquals(FinancialActivityAccountInvalidException.getErrorcode(), invalidFinancialActivityAccountError.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    /**
     * Should be able to delete a Financial Activity to Account Mapping *
     */
    Integer deletedFinancialActivityAccountId = financialActivityAccountHelper.deleteFinancialActivityAccount(financialActivityAccountId, responseSpec, CommonConstants.RESPONSE_RESOURCE_ID);
    Assert.assertNotNull(deletedFinancialActivityAccountId);
    Assert.assertEquals(financialActivityAccountId, deletedFinancialActivityAccountId);
    /**
     * Trying to fetch a Deleted Account Mapping should give me a 404 *
     */
    financialActivityAccountHelper.getFinancialActivityAccount(deletedFinancialActivityAccountId, responseSpecForResourceNotFoundError);
}

