    HashMap toSavingsSummaryAfter = this.savingsAccountHelper.getSavingsSummary(toSavingsId);
    Float toSavingsBalanceAfter = (Float) toSavingsSummaryAfter.get("accountBalance");
    final HashMap standingInstructionData = this.standingInstructionsHelper.getStandingInstructionById(standingInstructionId.toString());
    Float expectedFromSavingsBalance = fromSavingsBalanceBefore - (Float) standingInstructionData.get("amount");
    Float expectedToSavingsBalance = toSavingsBalanceBefore + (Float) standingInstructionData.get("amount");
    Assert.assertEquals("Verifying From Savings Balance after Successful completion of Scheduler Job", expectedFromSavingsBalance, fromSavingsBalanceAfter);
    Assert.assertEquals("Verifying To Savings Balance after Successful completion of Scheduler Job", expectedToSavingsBalance, toSavingsBalanceAfter);
